<script setup>
import { ref,onMounted } from 'vue'
import { api } from '../api'
const format=ref('json'),options=ref({kind:'all',start:'',end:'',include_questions:true,include_analysis:true,include_deleted:false,include_history:true,include_game:false}),busy=ref(false),error=ref(''),notice=ref(''),metrics=ref(null)
async function download(){if(busy.value)return;busy.value=true;error.value='';notice.value='';try{await api.exportData(format.value,format.value==='json'?{}:{...options.value,...(format.value==='csv'?{include_game:false}:{})});notice.value='文件已生成并开始下载。'}catch(e){error.value=e.message}finally{busy.value=false}}
onMounted(()=>api.flow('/record-metrics').then(value=>{metrics.value=value}).catch(e=>{error.value=e.message}))
</script>
<template><section class="card settings-section" id="settings-data"><h2 tabindex="-1">数据导出与日期指标</h2><p class="muted">默认 JSON 保留本人游戏数据。完整 v4 包含日记版本、问答和计划事实；旧 v3 可通过接口显式选择。导出文件不承诺直接导入恢复。</p><label>格式<select v-model="format"><option value="json">完整 JSON v4</option><option value="markdown">可读 Markdown</option><option value="html">离线 HTML</option><option value="csv">CSV · 每条记录一行</option></select></label>
<div v-if="format!=='json'"><label>记录类型<select v-model="options.kind"><option value="all">全部</option><option value="event">新事件</option><option value="diary">晚间日记</option><option value="legacy">旧记录 · 未分类</option></select></label><div class="form-grid"><label>内容起始日期<input type="date" v-model="options.start"/></label><label>内容结束日期<input type="date" v-model="options.end"/></label></div><label><input type="checkbox" v-model="options.include_questions"/>包含确切问题及对应回答/跳过</label><label><input type="checkbox" v-model="options.include_analysis"/>包含分析与来源</label><label><input type="checkbox" v-model="options.include_deleted"/>包含撤销记录</label><label><input type="checkbox" v-model="options.include_history"/>包含旧原文/分析版本</label><label v-if="format!=='csv'"><input type="checkbox" v-model="options.include_game"/>附本人全部日期的游戏数据</label><p v-if="format==='csv'" class="muted">CSV 为扁平表；问答/分析在 JSON 单元格内，不含全部游戏表或原文历史。需完整保留用 JSON。</p></div><button class="btn primary" :disabled="busy" @click="download">{{ busy?'导出中…':'生成并下载' }}</button><p v-if="error" class="error" role="alert">{{ error }}</p><p v-if="notice" role="status">{{ notice }}</p>
<details v-if="metrics"><summary>分别查看内容覆盖日与首次保存日</summary><p class="muted">候选口径 {{ metrics.policy_version }}；首次保存日按保存时捕获的时区固定，编辑不增加保存天数，缺失历史捕获日不猜测。未设正式坚持奖励口径，不新增授奖。旧未分类 {{ metrics.legacy_unclassified }} 条。</p><p v-for="(value,key) in metrics.metrics" :key="key">{{ key }}：{{ value.count }} 天 · 最长连续 {{ value.longest_contiguous_days }} 天</p></details></section></template>
